-- Baseline: the schema previously generated by Hibernate.
-- Existing databases are baselined at this version and skip this script
-- (spring.flyway.baseline-on-migrate); new databases run it.

CREATE TABLE users (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    email    VARCHAR(255) NOT NULL,
    password VARCHAR(255) NOT NULL,
    CONSTRAINT uk6dotkott2kjsp8vw4d0m25fb7 UNIQUE (email)
);

CREATE TABLE urls (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    click_count BIGINT,
    crt_at      DATETIME(6),
    expiry      DATETIME(6),
    long_url    TEXT         NOT NULL,
    short_code  VARCHAR(255) NOT NULL,
    user_id     BIGINT,
    CONSTRAINT uko6lree3tj9uru7b4vo07v6s1n UNIQUE (short_code),
    CONSTRAINT fk31nbxw9e1inas1lmdkwxqv10 FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE analytics_event (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    device      VARCHAR(255),
    referrer    VARCHAR(255),
    `timestamp` DATETIME(6),
    url_id      BIGINT,
    CONSTRAINT fkl2kx6jmo7b3jhmpvacnpv98vq FOREIGN KEY (url_id) REFERENCES urls (id)
);
